bad=0
for l in sorted(set(x[0] for x in F)):
    path='src/i18n/locales/%s.json'%l
    d=json.load(open(path,encoding='utf-8'))
    for lang,key,old,new in F:
        if lang!=l: continue
        cur=d; parts=key.split('.')
        for p in parts[:-1]: cur=cur[p]
        if cur[parts[-1]]!=old: print('NOT FOUND',l,key); bad+=1; continue
        cur[parts[-1]]=new
    open(path,'w',encoding='utf-8').write(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
print('done, mismatches:',bad)
